#!/usr/bin/env node
/**
 * Populate DirectoryEntry collection with the current unified directory data.
 *
 * Usage:
 *   node scripts/populate-directory.js
 *
 * It expects that the JSON file generated by getDirectoryData()
 * exists at data/reference-data-source/directory-view-source.json.
 * If not found, instruct the user to visit the directory page first.
 */
const path = require('path');
const fs = require('fs');
const mongoose = require('mongoose');
const DirectoryEntry = require('../models/DirectoryEntry');

(async () => {
  try {
    // Locate JSON source
    const jsonPath = path.join(process.cwd(), 'data', 'reference-data-source', 'directory-view-source.json');
    if (!fs.existsSync(jsonPath)) {
      console.error('Source JSON not found. Visit /reference-data/directory once to generate it.');
      process.exit(1);
    }

    const { items } = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));

    if (!Array.isArray(items) || items.length === 0) {
      console.error('No items found in JSON. Nothing to import.');
      process.exit(1);
    }

    // Connect to MongoDB (uses MONGODB_URI env or fallback localhost)
    const uri = process.env.MONGODB_URI || 'mongodb://localhost:27017/rrdm';
    await mongoose.connect(uri);
    console.log('Connected to MongoDB');

    const bulkOps = items.map(item => ({
      updateOne: {
        filter: {
          fieldName: item.fieldName,
          code: item.code,
          academicYear: item.academicYear
        },
        update: {
          $set: {
            label: item.label,
            status: item.status
          }
        },
        upsert: true
      }
    }));

        const result = await DirectoryEntry.bulkWrite(bulkOps, { ordered: false });
    const { upsertedCount = 0, modifiedCount = 0, matchedCount = 0 } = result;
    console.log(`Bulk import complete: upserted ${upsertedCount}, modified ${modifiedCount}, matched ${matchedCount}`);
    await mongoose.disconnect();
    process.exit(0);
  } catch (err) {
    console.error('Error populating DirectoryEntry:', err);
    process.exit(1);
  }
})();
